"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["65262"],{95399(e){e.exports=JSON.parse('{"id":"F368","slug":"asset-manager-economics","name":"Asset Manager Revenue and Fee Sensitivity","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Asset management firms","level":"Beginner","aliases":["asset management firms","AUM growth","fee compression","operating margin"],"formula":{"latex":"AUM_{1}=AUM_{0}(1+r)+F,\\\\quad \\\\text{Revenue}=\\\\bar{AUM}\\\\times f,\\\\quad \\\\text{Profit}=\\\\text{Revenue}\\\\times m","also":[],"text":"Ending AUM = starting AUM x (1 + market return) + net flows; Revenue = average AUM x fee rate; Operating profit = revenue x operating margin"},"symbols":[{"symbol":"AUM","meaning":"Assets under management","unit":"billions"},{"symbol":"F","meaning":"Net flows: new money in less money withdrawn","unit":"billions"},{"symbol":"f","meaning":"Average fee rate on AUM","unit":"percent"},{"symbol":"m","meaning":"Operating margin","unit":"percent"}],"when_to_use":"Use it to see what drives an asset manager\'s earnings. Revenue rises with markets and net inflows, and falls with fee cuts, since costs are largely fixed, so profit moves more than revenue. The shift to cheaper passive funds has been compressing fee rates for years, so the fee sensitivity is worth checking.","worked_example":{"problem":"A manager starts with 50 billion, the market returns 6% and net flows are +1.5 billion. The average fee is 0.45% and the operating margin 35%. Test a cut to 0.40%.","inputs":{"a0":50,"f":1.5,"r":6,"fee":0.45,"m":35,"fee2":0.4},"steps":[{"label":"Ending AUM","working":"50 x (1+0.06)+1.5","value":"54.50"},{"label":"AUM growth","working":"54.5 / 50-1","value":"9.0%"},{"label":"Average AUM","working":"(50+54.5) / 2","value":"52.25"},{"label":"Revenue = average AUM x fee","working":"52.25 x 0.0045","value":"0.235"},{"label":"Operating profit = revenue x margin","working":"0.235125 x 0.35","value":"0.082"},{"label":"Revenue at the lower fee","working":"52.25 x 0.004","value":"0.209"},{"label":"Profit at the lower fee, with costs unchanged = new revenue - old costs","working":"0.209-0.235125 x (1-0.35)","value":"0.056"},{"label":"Fall in profit","working":"0.0561687 / 0.0822937-1","value":"-31.7%"}],"answer":"Ending AUM is 54.50, up 9.0%, and average AUM is 52.25. Revenue is 0.235 and operating profit 0.082. If the fee rate fell to 0.40% with costs unchanged, revenue would be 0.209 and profit 0.056, a fall of -31.7% in profit."},"calculator":{"available":true,"inputs":[{"id":"a0","label":"Starting AUM (billions)","unit":"billions","type":"number","default":50,"hint":""},{"id":"f","label":"Net flows (billions)","unit":"billions","type":"number","default":1.5,"hint":""},{"id":"r","label":"Market return","unit":"%","type":"number","default":6,"hint":""},{"id":"fee","label":"Fee rate","unit":"%","type":"number","default":0.45,"hint":""},{"id":"m","label":"Operating margin","unit":"%","type":"number","default":35,"hint":""},{"id":"fee2","label":"Lower fee rate to test","unit":"%","type":"number","default":0.4,"hint":""}],"checks":[{"expr":"a0>0 and fee>0 and m>0 and m<1","message":"Enter positive values and a margin between 0 and 100%."}],"steps":[{"id":"a1","label":"Ending AUM","expr":"a0*(1+r)+f","format":"num2"},{"id":"gr","label":"AUM growth","expr":"a1/a0-1","format":"pct1"},{"id":"avg","label":"Average AUM","expr":"(a0+a1)/2","format":"num2"},{"id":"rev","label":"Revenue = average AUM x fee","expr":"avg*fee","format":"num3"},{"id":"prof","label":"Operating profit = revenue x margin","expr":"rev*m","format":"num3"},{"id":"rev2","label":"Revenue at the lower fee","expr":"avg*fee2","format":"num3"},{"id":"prof2","label":"Profit at the lower fee, with costs unchanged = new revenue - old costs","expr":"rev2-rev*(1-m)","format":"num3"},{"id":"dp","label":"Fall in profit","expr":"prof2/prof-1","format":"pct1"}],"results":["a1","rev","prof","dp"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"a1":54.5,"gr":0.09000000000000008,"avg":52.25,"rev":0.23512499999999997,"prof":0.08229374999999998,"rev2":0.209,"prof2":0.05616875000000002,"dp":-0.3174603174603171}},"finder":{"finds":"How AUM, fees and margin drive profit","needs":"AUM, flows, market return, fee, margin"},"related":[{"slug":"fee-drag","name":"Cost of Fees: Active vs. Passive"},{"slug":"hedge-fund-fees","name":"Hedge Fund Fees: Management, Performance, Hurdle and High-Water Mark"},{"slug":"tracking-difference","name":"Index Fund Tracking Difference and Error"}],"related_ids":["F244","F369","F114"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>A</mi><mi>U</mi><msub><mi>M</mi><mn>1</mn></msub><mo>=</mo><mi>A</mi><mi>U</mi><msub><mi>M</mi><mn>0</mn></msub><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo stretchy=\\"false\\">)</mo><mo>+</mo><mi>F</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Revenue</mtext><mo>=</mo><mover accent=\\"true\\"><mrow><mi>A</mi><mi>U</mi><mi>M</mi></mrow><mo>\u02C9</mo></mover><mo>\xd7</mo><mi>f</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Profit</mtext><mo>=</mo><mtext>Revenue</mtext><mo>\xd7</mo><mi>m</mi></mrow><annotation encoding=\\"application/x-tex\\">AUM_{1}=AUM_{0}(1+r)+F,\\\\quad \\\\text{Revenue}=\\\\bar{AUM}\\\\times f,\\\\quad \\\\text{Profit}=\\\\text{Revenue}\\\\times m</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"asian-option-payoff","name":"Asian Option Payoff"},"next":{"slug":"strategy-backtest-metrics","name":"Backtest Performance Metrics"},"lesson":{"name":"Lesson 4 \xb7 Ask a question worth answering","to":"/courses/financial-data-to-insight/ask-a-question-worth-answering"},"total":522}')}}]);